\begin{align*}
&z^{49} + z^{50} + z^{51} + z^{52} + z^{53} \\
=&z^{48}z + (z^{48}z^{3}) + (z^{48}z^{6}) + (z^{48}z^{9}) + (z^{48}z^{12}) \\
=&1\times \left(-\dfrac{1}{2} + \dfrac{\sqrt{3}}{2}i\right) + \left(1\times 1\right) + \left(1\times \left(-\dfrac{1}{2} - \dfrac{\sqrt{3}}{2}i\right)\right) + \left(\dfrac{\sqrt{3}}{2}i\times 1\right) + \left(-\dfrac{\sqrt{3}}{2}i\times \left(-\dfrac{1}{2} + \dfrac{\sqrt{3}}{2}i\right)\right) \\
=&\left(-\dfrac{1}{2}\sqrt{3}-\dfrac{1}{2}\right) - \left(-\dfrac{1}{2}\sqrt{3}+\dfrac{1}{2}\right) \\
=&-1.
\end{align*}
</answer>

